ALTER TABLE "product_own_delivery_prices" ADD CONSTRAINT "product_own_delivery_prices_destino_check" CHECK (("product_own_delivery_prices"."destination_type" = 'region' AND "product_own_delivery_prices"."region_id" IS NOT NULL AND "product_own_delivery_prices"."bairro_id" IS NULL AND "product_own_delivery_prices"."cep_especifico_id" IS NULL AND "product_own_delivery_prices"."city_id" IS NULL) OR ("product_own_delivery_prices"."destination_type" IN ('bairro', 'bairro-avulso') AND "product_own_delivery_prices"."region_id" IS NULL AND "product_own_delivery_prices"."bairro_id" IS NOT NULL AND "product_own_delivery_prices"."cep_especifico_id" IS NULL AND "product_own_delivery_prices"."city_id" IS NULL) OR ("product_own_delivery_prices"."destination_type" = 'cep-especifico' AND "product_own_delivery_prices"."region_id" IS NULL AND "product_own_delivery_prices"."bairro_id" IS NULL AND "product_own_delivery_prices"."cep_especifico_id" IS NOT NULL AND "product_own_delivery_prices"."city_id" IS NULL) OR ("product_own_delivery_prices"."destination_type" = 'cidade' AND "product_own_delivery_prices"."region_id" IS NULL AND "product_own_delivery_prices"."bairro_id" IS NULL AND "product_own_delivery_prices"."cep_especifico_id" IS NULL AND "product_own_delivery_prices"."city_id" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "product_own_delivery_prices" ADD CONSTRAINT "product_own_delivery_prices_valores_check" CHECK ("product_own_delivery_prices"."shipping_price" >= 0 AND ("product_own_delivery_prices"."scheduled_delivery_price" IS NULL OR "product_own_delivery_prices"."scheduled_delivery_price" >= 0) AND ("product_own_delivery_prices"."scheduled_delivery_min_days" IS NULL OR "product_own_delivery_prices"."scheduled_delivery_min_days" >= 0) AND (NOT "product_own_delivery_prices"."scheduled_delivery_active" OR ("product_own_delivery_prices"."scheduled_delivery_price" IS NOT NULL AND "product_own_delivery_prices"."scheduled_delivery_min_days" IS NOT NULL)));